begin;
with j as (select * from jsonb_to_recordset($law7d0008$[{"code_id":"APK_RF","article_number":"222.4","version_date":"2002-07-24","article_text":"1. Вопрос о принятии заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок к производству арбитражного суда решается судьей единолично в пятидневный срок со дня поступления такого заявления в суд.\n\n2. Арбитражный суд обязан принять к производству заявление о присуждении указанной в части 1 настоящей статьи компенсации, поданное с соблюдением установленных настоящим Кодексом требований к его форме и содержанию.\n\n3. Арбитражный суд выносит определение о принятии заявления о присуждении указанной в части 1 настоящей статьи компенсации к производству, в котором указываются время и место проведения судебного заседания по рассмотрению заявления.\n\n4. Копии определения о принятии заявления о присуждении указанной в части 1 настоящей статьи компенсации направляются заявителю, в орган, организацию или должностному лицу, на которые возложены обязанности по исполнению соответствующего судебного акта в связи с его неисполнением в разумный срок, что явилось основанием для обращения заявителя в суд с требованием о присуждении компенсации, а также другим заинтересованным лицам.","article_title":"Статья 222.4. Принятие заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок к производству арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8983b251e32883894d75bbc8f323d46bcc11fda276bf8781e3b56a0977e9d1d4"},{"code_id":"APK_RF","article_number":"222.5","version_date":"2002-07-24","article_text":"1. Если арбитражный суд при рассмотрении вопроса о принятии к производству заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок установит, что заявление подано с нарушением требований, установленных статьей 2223 настоящего Кодекса, или не уплачена государственная пошлина, суд выносит определение об оставлении заявления без движения.\n\n2. В определении арбитражный суд указывает основание для оставления заявления о присуждении компенсации, указанной в части 1 настоящей статьи, без движения и разумный срок, в течение которого должны быть устранены обстоятельства, послужившие основанием для оставления заявления без движения.\n\n3. Копия определения об оставлении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, без движения направляется лицу, подавшему заявление, не позднее следующего дня после дня вынесения определения.\n\n4. В случае, если обстоятельства, послужившие основанием для оставления заявления о присуждении компенсации, указанной в части 1 настоящей статьи, без движения, будут устранены в срок, установленный определением арбитражного суда, заявление считается поданным в день его первоначального поступления в суд. В других случаях заявление считается неподанным и возвращается с документами в порядке, установленном статьей 2226 настоящего Кодекса.","article_title":"Статья 222.5. Оставление заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"62ae40207d79aa6e4925911841254f505df8a56ea0041e52a06a68ede0876976"},{"code_id":"APK_RF","article_number":"222.6","version_date":"2002-07-24","article_text":"1. Арбитражный суд возвращает заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок, если при рассмотрении вопроса о принятии заявления к производству установит, что:\n\n1) заявление подано лицом, не имеющим права на его подачу;\n\n2) заявление подано с нарушением порядка и сроков, которые установлены частью 2 статьи 2221 и частью 1 статьи 2222 настоящего Кодекса. При этом ходатайство о восстановлении пропущенного срока подачи заявления не поступало или в восстановлении пропущенного срока его подачи было отказано;\n\n3) до вынесения определения о принятии заявления к производству арбитражного суда от лица, подавшего такое заявление, поступило ходатайство о его возвращении;\n\n4) не устранены обстоятельства, послужившие основанием для оставления заявления без движения, в срок, установленный определением арбитражного суда;\n\n5) срок судопроизводства по делу или срок исполнения судебного акта с очевидностью свидетельствует об отсутствии нарушения права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок.\n\n2. О возвращении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, арбитражный суд выносит определение.\n\n3. Копия определения о возвращении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, направляется заявителю вместе с заявлением и прилагаемыми к нему документами не позднее следующего дня после дня вынесения определения или по истечении срока, установленного арбитражным судом для устранения обстоятельств, послуживших основанием для оставления заявления без движения.\n\n4. Определение о возвращении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, может быть обжаловано в порядке и в сроки, которые установлены статьей 291 настоящего Кодекса.\n\nВ случае отмены определения заявление считается поданным в день его первоначального поступления в арбитражный суд.\n\n5. Возвращение заявления о присуждении компенсации, указанной в части 1 настоящей статьи, не препятствует повторному обращению заинтересованного лица с заявлением в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для возвращения заявления.","article_title":"Статья 222.6. Возвращение заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d7ac5ab4a27ae01b3f4e29d6bf0dbb73ed116e3b69544979c452980bb92f75a"},{"code_id":"APK_RF","article_number":"222.7","version_date":"2002-07-24","article_text":"Заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок рассматривается арбитражным судом в двухмесячный срок со дня поступления заявления вместе с делом в суд, включая срок на подготовку дела к судебному разбирательству и на принятие судебного акта.","article_title":"Статья 222.7. Срок рассмотрения заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f447acfb7d3ca0bd4873c37bf3bde7f7c8cca28295b0f30ce07a20b5ba3b8a5"},{"code_id":"APK_RF","article_number":"222.8","version_date":"2002-07-24","article_text":"1. Арбитражный суд рассматривает заявление о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок в судебном заседании коллегиальным составом судей по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными настоящей главой, и в соответствии с Федеральным законом \"О компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок\". Заявитель, орган, организация или должностное лицо, на которые возложены обязанности по исполнению судебного акта в связи с его неисполнением в разумный срок, что явилось основанием для обращения заявителя в суд с требованием о присуждении компенсации, а также другие заинтересованные лица извещаются о времени и месте судебного заседания.\n\n2. При рассмотрении заявления о присуждении компенсации, указанной в части 1 настоящей статьи, арбитражный суд устанавливает факт нарушения права заявителя на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок исходя из доводов, изложенных в заявлении, содержания принятых по делу судебных актов, из материалов дела и с учетом следующих обстоятельств:\n\n1) правовая и фактическая сложность дела;\n\n2) поведение заявителя и других участников арбитражного процесса;\n\n3) достаточность и эффективность действий суда или судьи, осуществляемых в целях своевременного рассмотрения дела;\n\n4) достаточность и эффективность осуществляемых в целях своевременного исполнения судебного акта действий органов, организаций или должностных лиц, на которые возложены обязанности по исполнению судебного акта;\n\n5) общая продолжительность судопроизводства по делу и неисполнения судебного акта.\n\n3. При подготовке дела к судебному разбирательству судья определяет круг заинтересованных лиц, в том числе орган, организацию, должностное лицо, которые не исполнили судебный акт в разумный срок, и устанавливает срок для представления ими объяснений, возражений и (или) доводов относительно заявления о присуждении компенсации, указанной в части 1 настоящей статьи. Орган, организация, должностное лицо обязаны представить объяснения, возражения и (или) доводы в срок, установленный арбитражным судом. Непредставление или несвоевременное представление объяснений, возражений и (или) доводов является основанием для наложения судебного штрафа в порядке и в размере, которые установлены главой 11 настоящего Кодекса.","article_title":"Статья 222.8. Особенности рассмотрения заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af37f89c274994738ac2957f76c2c29dd93bb38d8de97218ca5d06a7822ca0f1"},{"code_id":"APK_RF","article_number":"222.9","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок арбитражный суд принимает решение, которое должно содержать:\n\n1) наименование арбитражного суда, состав суда, принявшего решение;\n\n2) номер дела, по которому принято решение, дату и место принятия решения;\n\n3) наименование лица, подавшего заявление, и его процессуальное положение;\n\n4) наименование лиц, участвующих в деле, в том числе наименование органа, организации или должностного лица, на которые возложены обязанности по исполнению судебного акта;\n\n5) предмет заявления;\n\n6) фамилии лиц, присутствующих в судебном заседании, с указанием их полномочий;\n\n7) сведения о судебных актах, принятых по делу, предмет спора, наименование арбитражного суда, рассматривавшего дело;\n\n8) доводы, изложенные в заявлении;\n\n9) объяснения лиц, присутствовавших в судебном заседании;\n\n10) общую продолжительность судопроизводства по делу или общую продолжительность исполнения судебного акта;\n\n11) мотивы, по которым присуждается компенсация, или мотивы, по которым было отказано в ее присуждении;\n\n12) указание на присуждение компенсации и ее размер или отказ в присуждении компенсации;\n\n13) указание на действия, которые должны осуществить орган, организация или должностное лицо, на которые возложены обязанности по исполнению судебного акта.\n\n2. В решении арбитражного суда указывается на распределение судебных расходов, понесенных в связи с рассмотрением заявления о присуждении компенсации, указанной в части 1 настоящей статьи.\n\n3. Копии решения арбитражного суда направляются заявителю, в орган, организацию или должностному лицу, на которые возложены обязанности по исполнению судебного акта, в пятидневный срок со дня принятия такого решения.\n\n4. Решение арбитражного суда о присуждении компенсации, указанной в части 1 настоящей статьи, вступает в законную силу немедленно после его принятия, подлежит исполнению в порядке, установленном бюджетным законодательством Российской Федерации, и может быть обжаловано в кассационную инстанцию.","article_title":"Статья 222.9. Решение арбитражного суда по делу о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdc9beddf534bdc037923005be5ce9f3047297abf49c1805a40df4a0710363ad"},{"code_id":"APK_RF","article_number":"223","version_date":"2002-07-24","article_text":"1. Дела о несостоятельности (банкротстве) рассматриваются арбитражным судом по правилам, предусмотренным настоящим Кодексом, с особенностями, установленными федеральными законами, регулирующими вопросы несостоятельности (банкротства).\n\nАпелляционные жалобы на определения, вынесенные арбитражным судом при рассмотрении дел о несостоятельности (банкротстве), рассматриваются арбитражным судом апелляционной инстанции коллегиальным составом судей. (Дополнение абзацем - Федеральный закон от 28.11.2018 № 451-ФЗ)","article_title":"Статья 223. Порядок рассмотрения дел о несостоятельности (банкротстве)","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d89356373302d60c9f99931d05d4987c1afade552b759cd53c26067a5306a138"},{"code_id":"APK_RF","article_number":"224","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 29.06.2015 № 154-ФЗ)","article_title":"Статья 224. Право на обращение в арбитражный суд по делам о несостоятельности (банкротстве)","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c3d60583ea0025287e3d0b0bb40791bf751e16b915e3ccbb2398fe3e17de705b"},{"code_id":"APK_RF","article_number":"225","version_date":"2002-07-24","article_text":"По делам о несостоятельн\n\nости (банкротстве) может быть заключено мировое соглашение в соответствии с федеральным законом, а также допускаются иные примирительные процедуры, предусмотренные главой 15 настоящего Кодекса и другими федеральными законами, регулирующими вопросы несостоятельности (банкротства).\n\n(Дополнение главой - Федеральный закон от 19.07.2009 № 205-ФЗ)","article_title":"Статья 225. Примирение по делам о несостоятельности (банкротстве)","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a620827e1812368dcb92a8cf124bc7d6a355d9774897d3d88f041418b9ef8e3"},{"code_id":"APK_RF","article_number":"225.1","version_date":"2002-07-24","article_text":"1) споры, связанные с созданием, реорганизацией и ликвидацией юридического лица;\n\n2) споры, связанные с принадлежностью акций, долей в уставном (складочном) капитале хозяйственных обществ и товариществ, паев членов кооперативов, установлением их обременений и реализацией вытекающих из них прав (кроме споров, указанных в иных пунктах настоящей части), в частности споры, вытекающие из договоров купли-продажи акций, долей в уставном (складочном) капитале хозяйственных обществ, партнерств, товариществ, споры, связанные с обращением взыскания на акции и доли в уставном (складочном) капитале хозяйственных обществ, партнерств, товариществ, за исключением споров, вытекающих из деятельности депозитариев, связанной с учетом прав на акции и иные ценные бумаги, споров, возникающих в связи с разделом наследственного имущества или разделом общего имущества супругов, включающего в себя акции, доли в уставном (складочном) капитале хозяйственных обществ и товариществ, паи членов кооперативов;\n\n3) споры по искам учредителей, участников, членов юридического лица (далее - участники юридического лица) о возмещении убытков, причиненных юридическому лицу, признании недействительными сделок, совершенных юридическим лицом, и (или) применении последствий недействительности таких сделок;\n\n4) споры, связанные с назначением или избранием, прекращением, приостановлением полномочий и ответственностью лиц, входящих или входивших в состав органов управления и органов контроля юридического лица, споры, возникающие из гражданских правоотношений между указанными лицами и юридическим лицом в связи с осуществлением, прекращением, приостановлением полномочий указанных лиц, а также споры, вытекающие из соглашений участников юридического лица по поводу управления этим юридическим лицом, включая споры, вытекающие из корпоративных договоров;\n\n5) споры, связанные с эмиссией ценных бумаг, в том числе с оспариванием ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, должностных лиц, решений органов управления эмитента, с оспариванием сделок, совершенных в процессе размещения эмиссионных ценных бумаг, отчетов (уведомлений) об итогах выпуска (дополнительного выпуска) эмиссионных ценных бумаг;\n\n6) споры, вытекающие из деятельности держателей реестра владельцев ценных бумаг, связанной с учетом прав на акции и иные ценные бумаги, с осуществлением держателем реестра владельцев ценных бумаг иных прав и обязанностей, предусмотренных федеральным законом в связи с размещением и (или) обращением ценных бумаг;\n\n7) споры о созыве общего собрания участников юридического лица;\n\n8) споры об обжаловании решений органов управления юридического лица;\n\n9) споры, вытекающие из деятельности нотариусов по удостоверению сделок с долями в уставном капитале обществ с ограниченной ответственностью.\n\n1) споров, предусмотренных пунктами 7 и 9 части 1 настоящей статьи;\n\n2) споров, связанных с оспариванием ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, организаций, наделенных федеральным законом отдельными государственными или иными публичными полномочиями, должностных лиц;\n\n3) споров, предусмотренных частью 1 настоящей статьи, если на момент возбуждения дела в арбитражном суде или начала третейского разбирательства в третейском суде юридическим лицом, в отношении которого возникли такие споры, является хозяйственное общество, имеющее существенное значение для обеспечения обороны страны и безопасности государства в соответствии с Федеральным законом от 29 апреля 2008 года № 57-ФЗ \"О порядке осуществления иностранных инвестиций в хозяйственные общества, имеющие стратегическое значение для обеспечения обороны страны и безопасности государства\". Настоящий пункт не применяется к спорам, связанным с принадлежностью акций, долей в уставном (складочном) капитале юридических лиц, имеющих существенное значение для обеспечения обороны страны и безопасности государства в соответствии с указанным Федеральным законом, за исключением случаев, если такие споры вытекают из сделок с акциями, долями в уставном (складочном) капитале этих юридических лиц, подлежащих предварительному согласованию в соответствии с указанным Федеральным законом;\n\n4) споров, связанных с применением положений глав IX и XI1 Федерального закона от 26 декабря 1995 года № 208-ФЗ \"Об акционерных обществах\";\n\n5) споров, связанных с исключением участников юридических лиц, указанных в части 1 настоящей статьи.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 225.1. Дела по корпоративным спорам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5eacb913e21a1f8a6f288cfea485e446aeba4ae655baeff7248c6b8b18b6d75e"},{"code_id":"APK_RF","article_number":"225.10","version_date":"2002-07-24","article_text":"1. Гражданин или организация вправе обратиться в арбитражный суд в защиту прав и законных интересов группы лиц при наличии совокупности следующих условий:\n\n1) имеется общий по отношению к каждому члену группы лиц ответчик;\n\n2) предметом спора являются общие либо однородные права и законные интересы членов группы лиц;\n\n3) в основании прав членов группы лиц и обязанностей ответчика лежат схожие фактические обстоятельства;\n\n4) использование всеми членами группы лиц одинакового способа защиты своих прав.\n\n2. Под членами группы лиц в настоящей главе понимаются граждане и организации, отвечающие совокупности условий, указанных в части 1 настоящей статьи, независимо от присоединения их к требованию о защите прав и законных интересов группы лиц.\n\n3. В защиту прав и законных интересов группы лиц могут обратиться гражданин и организация, являющиеся членами этой группы лиц.\n\n4. В установленных федеральными законами случаях в защиту прав и законных интересов группы лиц также могут обратиться орган, организация и гражданин, не являющиеся членами этой группы лиц.\n\n5. Рассмотрение дела о защите прав и законных интересов группы лиц по правилам, установленным настоящей главой, допускается в случае, если ко дню обращения в арбитражный суд лиц, указанных в частях 3 и 4 настоящей статьи, к требованию о защите прав и законных интересов группы лиц присоединились не менее пяти лиц - членов группы лиц.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.10. Право на обращение в арбитражный суд в защиту прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c36be8df735e648ea76deb51a4fa2c3f45ea446b3cbbc5c9bacd93c05052636"},{"code_id":"APK_RF","article_number":"225.10-1","version_date":"2002-07-24","article_text":"1. В исковом заявлении, заявлении, поданных в защиту прав и законных интересов группы лиц, должно быть указано лицо, которому поручено ведение соответствующего дела в интересах группы лиц и которое должно быть членом данной группы лиц, за исключением случаев, предусмотренных частью 4 статьи 22510 настоящего Кодекса (далее в настоящей главе - лицо, которое ведет дело в интересах группы лиц). Лицо, которое ведет дело в интересах группы лиц, действует от имени группы лиц без доверенности на основании указанных в части 6 статьи 22510 настоящего Кодекса заявлений о присоединении к требованию о защите прав и законных интересов группы лиц.\n\n2. Если иное не предусмотрено соглашением группы лиц (статья 22516-1 настоящего Кодекса), лицо, которое ведет дело в интересах группы лиц, пользуется всеми процессуальными правами и несет процессуальные обязанности истца, в том числе обязанность по уплате судебных расходов. Такое лицо обязано добросовестно защищать права и законные интересы группы лиц. Если иное не предусмотрено соглашением группы лиц, лицо, которое ведет дело в интересах группы лиц, вправе поручить ведение дела представителю.\n\n3. Арбитражный суд вправе наложить судебный штраф на лицо, которое ведет дело в интересах группы лиц, в случае злоупотребления им своими процессуальными правами или в случае невыполнения им своих процессуальных обязанностей, в том числе в случае, если это лицо поручило ведение дела представителю.\n\n4. Полномочия лица, которое ведет дело в интересах группы лиц, прекращаются арбитражным судом:\n\n1) в случае отказа лица, которое ведет дело в интересах группы лиц, от иска;\n\n2) по требованию большинства лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, в случае обнаружения неспособности лица, которое ведет дело в интересах группы лиц, к ведению дела, в том числе в случае длительного отсутствия ввиду болезни, отпуска, в случае пребывания на учебе или нахождения в служебной командировке, либо при наличии обоснованных сомнений в ведении им дела разумно и добросовестно в интересах группы лиц.\n\n(Дополнение статьей - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.10-1. Ведение дел о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da2aea712a834e452b3ccce44c48aae6555e949ecc59535d143e65bdbc0141e6"},{"code_id":"APK_RF","article_number":"225.10-2","version_date":"2002-07-24","article_text":"1. Лицо, присоединившееся к требованию о защите прав и законных интересов группы лиц, имеет право:\n\n1) знакомиться с материалами дела, делать выписки из них, снимать копии;\n\n2) ходатайствовать в арбитражном суде о замене лица, которое ведет дело в интересах группы лиц, в том числе после принятия судебного акта, которым заканчивается рассмотрение дела по существу;\n\n3) присутствовать в судебном заседании, в том числе если оно объявлено закрытым;\n\n4) отказаться от поданного им заявления о присоединении к требованию о защите прав и законных интересов группы лиц.\n\n2. Члены группы лиц, несогласные с предъявленным требованием о защите прав и законных интересов группы лиц, вправе вступить в дело в качестве третьих лиц, не заявляющих самостоятельных требований относительно предмета спора.\n\n(Дополнение статьей - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.10-2. Права лица, присоединившегося к требованию о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"471b474381fa43ff6ad20e9d8ceb3cc75738ebba2e6fdc98d1267664abb00731"},{"code_id":"APK_RF","article_number":"225.11","version_date":"2002-07-24","article_text":"(Статья утратила силу - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.11. .","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d24801378a77c2e050518c898cc9003bce6b71cd2cf7b8cadb27f5080cda4b49"},{"code_id":"APK_RF","article_number":"225.12","version_date":"2002-07-24","article_text":"(Статья утратила силу - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.12. .","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d24801378a77c2e050518c898cc9003bce6b71cd2cf7b8cadb27f5080cda4b49"},{"code_id":"APK_RF","article_number":"225.13","version_date":"2002-07-24","article_text":"1. Исковое заявление, заявление, подаваемые в защиту прав и законных интересов группы лиц, должны соответствовать требованиям, предусмотренным статьей 125 настоящего Кодекса, а также иным требованиям к форме и содержанию искового заявления, заявления, установленным настоящим Кодексом для отдельных категорий дел. В исковом заявлении, заявлении, подаваемым в защиту прав и законных интересов группы лиц, также указываются:\n\n1) права и законные интересы группы лиц, в защиту которых предъявлено требование о защите прав и законных интересов группы лиц;\n\n2) круг лиц, являющихся членами группы лиц, основания такого членства;\n\n3) наименование лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, адрес или в случае, если лицом, присоединившимся к требованию о защите прав и законных интересов группы лиц, является гражданин, его место жительства или место пребывания, дата и место его рождения, место его работы или дата и место его государственной регистрации в качестве индивидуального предпринимателя при их наличии.\n\n2. К исковому заявлению, заявлению, подаваемым в защиту прав и законных интересов группы лиц, прилагаются документы, предусмотренные статьей 126 настоящего Кодекса, и иные документы в соответствии с требованиями настоящего Кодекса, установленными к исковому заявлению, заявлению по отдельным категориям дел. К исковому заявлению, заявлению, подаваемым в защиту прав и законных интересов группы лиц, также прилагаются документы, подтверждающие присоединение к требованию о защите прав и законных интересов группы лиц, указанных в пункте 3 части 1 настоящей статьи, и их принадлежность к группе лиц.\n\n3. В исковом заявлении, подаваемом в защиту прав и законных интересов группы лиц органом, организацией или гражданином, которые не являются членами группы лиц, должна содержаться ссылка на федеральный закон, устанавливающий право органа, организации или гражданина, которые не являются членами группы лиц, на обращение в суд в защиту прав и законных интересов группы лиц, а также должно быть указано, в чем конкретно заключаются интересы членов группы лиц, какие их права нарушены.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.13. Требования к исковому заявлению, заявлению, подаваемым в защиту прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b8c7c919f2d55112a29e0cd6aca3bb984db204b3a4cd3d419968f89d57dab4d2"},{"code_id":"APK_RF","article_number":"225.14","version_date":"2002-07-24","article_text":"1. При подготовке дела о защите прав и законных интересов группы лиц к судебному разбирательству судья:\n\n1) определяет характер спорного правоотношения и подлежащее применению законодательство;\n\n2) уточняет требования о защите прав и законных интересов группы лиц и основания этих требований;\n\n3) решает вопрос о составе группы лиц и о возможности установления иных лиц, являющихся участниками спорных правоотношений, о привлечении их к участию в деле;\n\n4) предлагает представить доказательства, подтверждающие принадлежность конкретного лица к группе лиц;\n\n5) предлагает лицам, присоединившимся к требованию о защите прав и законных интересов группы лиц, заключить соглашение группы лиц (статья 22516-1 настоящего Кодекса) или присоединиться к ранее заключенному такому соглашению;\n\n6) совершает иные предусмотренные статьей 135 настоящего Кодекса действия.\n\n2. В определении о подготовке дела к судебному разбирательству арбитражный суд устанавливает срок, в течение которого лицо, которое ведет дело в интересах группы лиц, должно предложить другим лицам из этой группы присоединиться к требованию о защите прав и законных интересов группы лиц.\n\n1) наименование ответчика и его адрес;\n\n2) наименование лица, обратившегося в защиту прав и законных интересов группы лиц, и (или) лица, которое ведет дело в интересах группы лиц;\n\n3) требование группы лиц;\n\n4) наименование арбитражного суда, в производстве которого находится дело, номер данного дела;\n\n5) срок, который установлен арбитражным судом и в течение которого иные лица, являющиеся членами группы лиц, могут присоединиться к требованию о защите их прав и законных интересов, рассматриваемому арбитражным судом, путем направления заявления о присоединении к данному требованию лицу, которое ведет дело в интересах группы лиц, и (или) в арбитражный суд;\n\n6) иную определяемую арбитражным судом информацию.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.14. Подготовка дела о защите прав и законных интересов группы лиц к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f05e201b2bb66c81dea72fcd87a78c04aa9fd7a2d936a97a2da6ee7b37388d9"}]$law7d0008$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
